#if CONFIG_IOB_BUFSIZE < 1518
#  error "CONFIG_RK3576_GMAC: CONFIG_IOB_BUFSIZE must hold a full frame"
#endif

#if (CONFIG_IOB_BUFSIZE % 4) != 0
#  error "CONFIG_RK3576_GMAC: CONFIG_IOB_BUFSIZE must be a whole DMA beat"
#endif

