#  warning "CONFIG_IOB_BUFSIZE is not a multiple of 16; the AXI data width"
#  warning "of the RK3576 GMAC may require it and RBSZ is programmed to it"
#endif

#define GM_BUFSIZE         CONFIG_IOB_BUFSIZE

