#ifdef CONFIG_NETDEV_IOCTL
/****************************************************************************
 * Name: gm_ioctl
 *
 * Description:
 *   SIOCGMIIPHY / SIOCGMIIREG / SIOCSMIIREG pass through to the controller's
 *   MDIO bus, which is what lets an `ifconfig`-style tool read the PHY.
 *
 ****************************************************************************/

static int gm_ioctl(FAR struct netdev_lowerhalf_s *dev, int cmd,
                    unsigned long arg)
{
  FAR struct rk3576_gmac_s *priv = (FAR struct rk3576_gmac_s *)dev;
  FAR struct mii_ioctl_data_s *mii = (FAR struct mii_ioctl_data_s *)arg;
  uint16_t value;
  int ret;

  switch (cmd)
    {
      case SIOCGMIIPHY:
        mii->phy_id = priv->phyaddr;
        return OK;

      case SIOCGMIIREG:
        ret = gm_mdio_read(priv, mii->phy_id, mii->reg_num, &value);
        if (ret < 0)
          {
            return ret;
          }

        mii->val_out = value;
        return OK;

      case SIOCSMIIREG:
        return gm_mdio_write(priv, mii->phy_id, mii->reg_num, mii->val_in);

      default:
        return -ENOTTY;
    }
}
#endif

/****************************************************************************
 * Name: gm_mac_start / gm_mac_stop
 *
 * Description:
 *   Bring the MAC and the DMA up in the order the controller expects: MTL
 *   queues first, then the MAC's address and filter, then the DMA rings,
 *   then the enables.  Undo it in the reverse order.
 *
 ****************************************************************************/

static void gm_mac_start(FAR struct rk3576_gmac_s *priv)
{
  /* MTL: store-and-forward on both directions, one TX queue enabled. */

  gm_putreg(priv, RK3576_GMAC_MTL_TXQ0_OPERATION_MODE,
            RK3576_GMAC_MTL_TXQ0_TSF |
            RK3576_GMAC_MTL_TXQ0_TXQEN_ENABLE);
  gm_putreg(priv, RK3576_GMAC_MTL_RXQ0_OPERATION_MODE,
            RK3576_GMAC_MTL_RXQ0_RSF);

  /* MAC: RX queue 0 enabled for generic traffic, address and filter. */

  gm_putreg(priv, RK3576_GMAC_MAC_RXQ_CTRL0, 2);
  gm_mac_address(priv);

  /* Strip the pad and the CRC on receive: the stack wants the frame, not the
   * wire.  Jabber disabled, jumbo and 2K packets off.  Speed and duplex come
   * from gm_set_speed when the link settles.
   */

  gm_putreg(priv, RK3576_GMAC_MAC_CONFIGURATION,
            RK3576_GMAC_CONFIG_JD | RK3576_GMAC_CONFIG_ACS |
            RK3576_GMAC_CONFIG_CST);

  gm_dma_setup(priv);

  /* Clear anything the previous session left pending, then enable. */

  gm_putreg(priv, RK3576_GMAC_DMA_CH0_STATUS, GM_IRQ_STATUS);
  gm_putreg(priv, RK3576_GMAC_DMA_CH0_INTERRUPT_ENABLE, GM_IRQ_ENABLE);

  gm_putreg(priv, RK3576_GMAC_DMA_CH0_RX_CONTROL,
            gm_getreg(priv, RK3576_GMAC_DMA_CH0_RX_CONTROL) |
            RK3576_GMAC_CH0RX_SR);
  gm_putreg(priv, RK3576_GMAC_DMA_CH0_TX_CONTROL,
            gm_getreg(priv, RK3576_GMAC_DMA_CH0_TX_CONTROL) |
            RK3576_GMAC_CH0TX_ST);

  gm_putreg(priv, RK3576_GMAC_MAC_CONFIGURATION,
            gm_getreg(priv, RK3576_GMAC_MAC_CONFIGURATION) |
            RK3576_GMAC_CONFIG_RE | RK3576_GMAC_CONFIG_TE);
}

static void gm_mac_stop(FAR struct rk3576_gmac_s *priv)
{
  uint32_t timeout;

  /* Stop the DMA first, then the MAC, then wait for the queues to drain so
   * that no descriptor is still being written when the buffers are freed.
   */

  gm_putreg(priv, RK3576_GMAC_DMA_CH0_INTERRUPT_ENABLE, 0);
  gm_putreg(priv, RK3576_GMAC_DMA_CH0_TX_CONTROL,
            gm_getreg(priv, RK3576_GMAC_DMA_CH0_TX_CONTROL) &
            ~RK3576_GMAC_CH0TX_ST);
  gm_putreg(priv, RK3576_GMAC_DMA_CH0_RX_CONTROL,
            gm_getreg(priv, RK3576_GMAC_DMA_CH0_RX_CONTROL) &
            ~RK3576_GMAC_CH0RX_SR);

  gm_putreg(priv, RK3576_GMAC_MAC_CONFIGURATION,
            gm_getreg(priv, RK3576_GMAC_MAC_CONFIGURATION) &
            ~(RK3576_GMAC_CONFIG_RE | RK3576_GMAC_CONFIG_TE));

  for (timeout = GM_RESET_TIMEOUT; timeout > 0; timeout--)
    {
      if ((gm_getreg(priv, RK3576_GMAC_DMA_CH0_RX_CONTROL) &
           RK3576_GMAC_CH0RX_SR) == 0)
        {
          break;
        }

      up_udelay(1);
    }

  up_mdelay(1);
  gm_putreg(priv, RK3576_GMAC_DMA_CH0_STATUS, GM_IRQ_STATUS);
}

/****************************************************************************
 * Private Functions: link state machine
 ****************************************************************************/

/****************************************************************************
 * Name: gm_link_work
 *
 * Description:
 *   Poll the PHY once a second and tell the stack when the carrier or the
 *   negotiated rate changes.
 *
 *   The carrier notifier takes the per-device network lock, so this cannot
 *   run in an interrupt: it is a work item on the low-priority queue, which
 *   is what the lower half's `priority` field is set to.
 *
 ****************************************************************************/

static void gm_link_work(FAR void *arg)
{
  FAR struct rk3576_gmac_s *priv = arg;
  bool up;
  bool changed;
  int ret;
  irqstate_t flags;

  if (!priv->started)
    {
      return;
    }

  ret = gm_phy_link(priv, &up);
  if (ret < 0 && ret != -EAGAIN)
    {
      syslog(LOG_ERR, "gmac%d: PHY read failed: %d\n", priv->intf, ret);
      goto rearm;
    }

  flags = spin_lock_irqsave(&priv->lock);

  changed = up != priv->carrier;

  if (up && ret == OK)
    {
      /* A rate or duplex change needs the MAC reprogrammed, and that must
       * happen with the receiver and transmitter off.
       */

      bool reconfig = changed;

      if (!changed && priv->started)
        {
          /* Same link state: only reprogram if what was negotiated differs
           * from what we programmed.  gm_phy_link() has already stored the
           * new values, so compare against what the MAC currently says.
           */

          uint32_t config = gm_getreg(priv,
                                      RK3576_GMAC_MAC_CONFIGURATION);
          uint32_t want = 0;

          if (priv->full_duplex)
            {
              want |= RK3576_GMAC_CONFIG_DM;
            }

          if (priv->speed != 1000)
            {
              want |= RK3576_GMAC_CONFIG_PS;
            }

          if (priv->speed == 100)
            {
              want |= RK3576_GMAC_CONFIG_FES;
            }

          reconfig = (config & (RK3576_GMAC_CONFIG_DM |
                                RK3576_GMAC_CONFIG_PS |
                                RK3576_GMAC_CONFIG_FES)) !=
                     (want | (config & RK3576_GMAC_CONFIG_DM ?
                              RK3576_GMAC_CONFIG_DM : 0));
        }

      if (reconfig)
        {
          uint32_t config = gm_getreg(priv,
                                      RK3576_GMAC_MAC_CONFIGURATION);

          gm_putreg(priv, RK3576_GMAC_MAC_CONFIGURATION,
                    config & ~(RK3576_GMAC_CONFIG_RE |
                               RK3576_GMAC_CONFIG_TE));
          gm_set_speed(priv);
          gm_putreg(priv, RK3576_GMAC_MAC_CONFIGURATION,
                    gm_getreg(priv, RK3576_GMAC_MAC_CONFIGURATION) |
                    RK3576_GMAC_CONFIG_RE | RK3576_GMAC_CONFIG_TE);
        }

      priv->carrier = true;
    }
  else if (!up)
    {
      priv->carrier = false;
    }

  spin_unlock_irqrestore(&priv->lock, flags);

  if (changed)
    {
      if (up)
        {
          syslog(LOG_INFO, "gmac%d: link up %uM %s duplex\n", priv->intf,
                 priv->speed, priv->full_duplex ? "full" : "half");
          netdev_lower_carrier_on(&priv->dev);
        }
      else
        {
          syslog(LOG_INFO, "gmac%d: link down\n", priv->intf);
          netdev_lower_carrier_off(&priv->dev);
        }
    }

rearm:
  if (priv->started)
    {
      work_queue(LPWORK, &priv->linkwork, gm_link_work, priv,
                 MSEC2TICK(GM_LINK_POLL_MS));
    }
}

/****************************************************************************
 * Name: gm_ifup
 *
 * Description:
 *   Bring the port up.  This runs on the thread that issues `ifup eth0` and
 *   may sleep, which is what MDIO, the PHY reset and the clock enables want.
 *
 ****************************************************************************/

static int gm_ifup(FAR struct netdev_lowerhalf_s *dev)
{
  FAR struct rk3576_gmac_s *priv = (FAR struct rk3576_gmac_s *)dev;
  int ret;

  if (priv->started)
    {
      return OK;
    }

  if (priv->cfg->pinmux != NULL)
    {
      ret = priv->cfg->pinmux();
      if (ret < 0)
        {
          syslog(LOG_ERR, "gmac%d: pinmux failed: %d\n", priv->intf, ret);
          return ret;
        }
    }

  if (priv->cfg->phy_reset != NULL)
    {
      priv->cfg->phy_reset(true);
      up_mdelay(20);
      priv->cfg->phy_reset(false);
      up_mdelay(100);
    }

  ret = gm_reset(priv);
  if (ret < 0)
    {
      return ret;
    }

  /* Probe again if the first probe at boot found nothing: a module or a
   * cable may have been added since, and this is the second chance.
   */

  if (priv->phyaddr == 0xff)
    {
      ret = gm_phy_probe(priv);
      if (ret < 0)
        {
          return ret;
        }
    }

  ret = gm_phy_start(priv);
  if (ret < 0)
    {
      syslog(LOG_ERR, "gmac%d: autonegotiation could not be started: %d\n",
             priv->intf, ret);
      return ret;
    }

  ret = gm_rings_alloc(priv);
  if (ret < 0)
    {
      goto errout;
    }

  /* Until the link settles the MAC runs at gigabit; gm_link_work corrects
   * this as soon as the PHY says what was negotiated.
   */

  priv->speed = 1000;
  priv->full_duplex = true;
  priv->carrier = false;

  gm_mac_start(priv);
  priv->started = true;

  irq_attach(priv->irq, gm_interrupt, priv);
  up_enable_irq(priv->irq);

  work_queue(LPWORK, &priv->linkwork, gm_link_work, priv, 0);
  return OK;

errout:
  gm_rings_free(priv);
  return ret;
}

/****************************************************************************
 * Name: gm_ifdown
 *
 ****************************************************************************/

static int gm_ifdown(FAR struct netdev_lowerhalf_s *dev)
{
  FAR struct rk3576_gmac_s *priv = (FAR struct rk3576_gmac_s *)dev;

  if (!priv->started)
    {
      return OK;
    }

  priv->started = false;

  work_cancel(LPWORK, &priv->linkwork);
  work_cancel(LPWORK, &priv->rxretry);

  up_disable_irq(priv->irq);
  irq_detach(priv->irq);

  gm_mac_stop(priv);
  gm_rings_free(priv);

  if (priv->carrier)
    {
      priv->carrier = false;
      netdev_lower_carrier_off(dev);
    }

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: rk3576_gmac_initialize
 *
 * Description:
 *   Platform bring-up and registration.  Everything that must happen once
 *   happens here; everything that must happen per `ifup` happens in gm_ifup.
 *
 ****************************************************************************/

int rk3576_gmac_initialize(int intf,
                           FAR const struct rk3576_gmac_config_s *cfg)
{
  FAR struct rk3576_gmac_s *priv;
  uint32_t version;
  int ret;

  if (cfg == NULL || cfg->mac == NULL)
    {
      return -EINVAL;
    }

  if (intf != RK3576_GMAC0 && intf != RK3576_GMAC1)
    {
      return -EINVAL;
    }

  priv = kmm_zalloc(sizeof(struct rk3576_gmac_s));
  if (priv == NULL)
    {
      return -ENOMEM;
    }

  priv->cfg = cfg;
  priv->intf = intf;
  priv->base = intf == RK3576_GMAC0 ? RK3576_GMAC0_ADDR : RK3576_GMAC1_ADDR;
  priv->irq = intf == RK3576_GMAC0 ? RK3576_IRQ_GMAC0_SBD :
                                     RK3576_IRQ_GMAC1_SBD;
  priv->phyaddr = 0xff;
  spin_lock_init(&priv->lock);

  /* The board's own half first: without the pads muxed and the PHY out of
   * reset, nothing below can work.
   */

  if (cfg->pinmux != NULL)
    {
      ret = cfg->pinmux();
      if (ret < 0)
        {
          syslog(LOG_ERR, "gmac%d: pinmux failed: %d\n", intf, ret);
          goto errout;
        }
    }

  if (cfg->phy_reset != NULL)
    {
      cfg->phy_reset(true);
      up_mdelay(20);
      cfg->phy_reset(false);
      up_mdelay(100);
    }

  ret = gm_clocks(priv);
  if (ret < 0)
    {
      goto errout;
    }

  ret = gm_reset(priv);
  if (ret < 0)
    {
      goto errout;
    }

  ret = gm_rgmii_mode(priv);
  if (ret < 0)
    {
      goto errout;
    }

  ret = gm_delays(priv);
  if (ret < 0)
    {
      goto errout;
    }

  /* The aliveness test: a powered, clocked, un-gated controller reads back
   * 0x00003051, a dead one reads zero.  One read separates "our code is
   * wrong" from "the block is not there".
   */

  version = gm_getreg(priv, RK3576_GMAC_MAC_VERSION);
  syslog(LOG_INFO, "gmac%d: version 0x%08" PRIx32 "\n", intf, version);

  if (version != GM_MAC_VERSION)
    {
      syslog(LOG_ERR, "gmac%d: controller did not answer (expected "
             "0x%08x)\n", intf, GM_MAC_VERSION);
      ret = -ENODEV;
      goto errout;
    }

  ret = gm_phy_probe(priv);
  if (ret < 0)
    {
      /* A missing PHY must not stop the board from booting, and it must not
       * stop the port from existing: ifup probes again.
       */

      syslog(LOG_WARNING, "gmac%d: no PHY at boot, will retry on ifup\n",
             intf);
      priv->phyaddr = 0xff;
    }

  memcpy(&priv->dev.netdev.d_mac.ether, cfg->mac, sizeof(struct ether_addr));

  priv->dev.ops = &g_gm_ops;
  priv->dev.quota[NETPKT_TX] = GM_TX_QUOTA;
  priv->dev.quota[NETPKT_RX] = GM_RX_QUOTA;
  priv->dev.rxtype = NETDEV_RX_WORK;
  priv->dev.priority = LPWORK;

  ret = netdev_lower_register(&priv->dev, NET_LL_ETHERNET);
  if (ret < 0)
    {
      syslog(LOG_ERR, "gmac%d: netdev_lower_register failed: %d\n", intf,
             ret);
      goto errout;
    }

  syslog(LOG_INFO, "gmac%d: registered as %s, mac %02x:%02x:%02x:%02x:%02x"
         ":%02x\n", intf, priv->dev.netdev.d_ifname, cfg->mac[0], cfg->mac[1],
         cfg->mac[2], cfg->mac[3], cfg->mac[4], cfg->mac[5]);
  return OK;

errout:
  kmm_free(priv);
  return ret;
}

#endif /* CONFIG_RK3576_GMAC */

