static int eth_phy_read(FAR struct eth_phy_s *phy, uint8_t regaddr,
                        FAR uint16_t *value)
{
  return phy->bus->read(phy->bus->arg, phy->addr, regaddr, value);
}

static int eth_phy_write(FAR struct eth_phy_s *phy, uint8_t regaddr,
                         uint16_t value)
{
  return phy->bus->write(phy->bus->arg, phy->addr, regaddr, value);
}

/****************************************************************************
 * Name: eth_phy_present
 *
 * Description:
 *   Is there a PHY at this address?
 *
 *   A part with ID registers behind it can be identified by reading them, but
 *   some parts -- the MAE0621A among them -- do not implement registers 2 and
 *   3 at all, and an absent MDIO address reads back all-ones or all-zeros.
 *   So presence is: BMSR readable, extended-capability bit set, and neither of
 *   the two "nothing there" patterns.
 *
 ****************************************************************************/

static bool eth_phy_present(FAR struct eth_phy_s *phy, uint8_t addr)
{
  uint16_t bmsr;
  uint8_t saved = phy->addr;

  phy->addr = addr;

  if (eth_phy_read(phy, MII_MSR, &bmsr) < 0)
    {
      phy->addr = saved;
      return false;
    }

  phy->addr = saved;

  if (bmsr == 0xffff || bmsr == 0x0000)
    {
      return false;
    }

  if (phy->desc->has_id)
    {
      uint16_t id1;
      uint16_t id2;

      if (eth_phy_read(phy, MII_PHYID1, &id1) < 0 ||
          eth_phy_read(phy, MII_PHYID2, &id2) < 0)
        {
          return false;
        }

      /* An MDIO address with nothing behind it reads the same as a PHY whose
       * ID is zero, so a part that claims ID registers must also show a
       * non-zero OUI half.
       */

      if ((id1 & 0x3fff) == 0 || (id1 & 0x3fff) == 0x3fff)
        {
          return false;
        }
    }
  else if ((bmsr & MII_MSR_EXTCAP) == 0)
    {
      return false;
    }

  return true;
}

/****************************************************************************
 * Name: eth_phy_search
 *
 * Description:
 *   The board's strap value first, then zero if the part answers there too,
 *   then the rest of the bus.  The last step is what makes a mis-strapped
 *   board usable instead of dead, and the log says which address won.
 *
 ****************************************************************************/

static int eth_phy_search(FAR struct eth_phy_s *phy)
{
  uint8_t addr;

  phy->addr = phy->desc->strapaddr;
  if (eth_phy_present(phy, phy->addr))
    {
      return OK;
    }

  if (phy->desc->try_zero)
    {
      phy->addr = 0;
      if (phy->eth_phy_present_hook)
        {
        }
    }

  return -ENODEV;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

FAR struct eth_phy_s *
eth_phy_initialize(FAR const struct eth_phy_bus_s *bus,
                   FAR const struct eth_phy_desc_s *desc)
{
  FAR struct eth_phy_s *phy;

  if (bus == NULL || desc == NULL || bus->read == NULL || bus->write == NULL)
    {
      return NULL;
    }

  phy = kmm_zalloc(sizeof(struct eth_phy_s));
  if (phy == NULL)
    {
      return NULL;
    }

  phy->bus = bus;
  phy->desc = desc;
  phy->addr = ETH_PHY_ADDR_NONE;

  if (eth_phy_search(phy) < 0)
    {
      syslog(LOG_ERR, "phy: %s did not answer on the MDIO bus\n", desc->name);
      kmm_free(phy);
      return NULL;
    }

  syslog(LOG_INFO, "phy: %s at address %u\n", desc->name, phy->addr);
  return phy;
}

void eth_phy_uninitialize(FAR struct eth_phy_s *phy)
{
  if (phy != NULL)
    {
      kmm_free(phy);
    }
}

uint8_t eth_phy_addr(FAR struct eth_phy_s *phy)
{
  return phy != NULL ? phy->addr : ETH_PHY_ADDR_NONE;
}

FAR const char *eth_phy_name(FAR struct eth_phy_s *phy)
{
  return phy != NULL ? phy->desc->name : "no phy";
}

int eth_phy_start(FAR struct eth_phy_s *phy)
{
  int ret;

  if (phy == NULL)
    {
      return -ENODEV;
    }

  ret = eth_phy_write(phy, MII_ADVERTISE, phy->desc->anar);
  if (ret < 0)
    {
      return ret;
    }

  ret = eth_phy_write(phy, ETH_PHY_CTRL1000, phy->desc->gbcr);
  if (ret < 0)
    {
      return ret;
    }

  return eth_phy_write(phy, MII_MCR, MII_MCR_ANENABLE | MII_MCR_ANRESTART);
}

int eth_phy_link(FAR struct eth_phy_s *phy, FAR struct eth_phy_link_s *link)
{
  uint16_t bmsr;
  uint16_t stat1000;
  uint16_t lpa;
  uint16_t anar;
  int ret;

  if (phy == NULL || link == NULL)
    {
      return -EINVAL;
    }

  link->up = false;
  link->speed = 0;
  link->full_duplex = false;

  /* Twice: the link bit latches low, so the first read after a link loss
   * still says "up".
   */

  ret = eth_phy_read(phy, MII_MSR, &bmsr);
  if (ret < 0)
    {
      return ret;
    }

  ret = eth_phy_read(phy, MII_MSR, &bmsr);
  if (ret < 0)
    {
      return ret;
    }

  if ((bmsr & MII_MSR_LINKSTATUS) == 0)
    {
      return OK;
    }

  link->up = true;

  if ((bmsr & MII_MSR_ANEGCOMPLETE) == 0)
    {
      return -EAGAIN;
    }

  /* 1000BASE-T first: the negotiated gigabit result appears in register 10
   * and nowhere else.  Registers 4 and 5 describe 10/100 only.
   */

  ret = eth_phy_read(phy, ETH_PHY_STAT1000, &stat1000);
  if (ret < 0)
    {
      return ret;
    }

  if ((stat1000 & (ETH_PHY_LPA_1000FULL | ETH_PHY_LPA_1000HALF)) != 0)
    {
      link->speed = 1000;
      link->full_duplex = (stat1000 & ETH_PHY_LPA_1000FULL) != 0;
      return OK;
    }

  ret = eth_phy_read(phy, MII_LPA, &lpa);
  if (ret < 0)
    {
      return ret;
    }

  ret = eth_phy_read(phy, MII_ADVERTISE, &anar);
  if (ret < 0)
    {
      return ret;
    }

  /* Only what both sides offered can be used. */

  lpa &= anar & ETH_PHY_ANAR_10_100;

  if (lpa & MII_ADVERTISE_100BASETXFULL)
    {
      link->speed = 100;
      link->full_duplex = true;
    }
  else if (lpa & MII_ADVERTISE_100BASETXHALF)
    {
      link->speed = 100;
      link->full_duplex = false;
    }
  else if (lpa & MII_ADVERTISE_10BASETXFULL)
    {
      link->speed = 10;
      link->full_duplex = true;
    }
  else if (lpa & MII_ADVERTISE_10BASETXHALF)
    {
      link->speed = 10;
      link->full_duplex = false;
    }
  else
    {
      /* Link is up but nothing in common: keep polling. */

      return -EAGAIN;
    }

  return OK;
}

int eth_phy_read_reg(FAR struct eth_phy_s *phy, uint8_t regaddr,
                     FAR uint16_t *value)
{
  if (phy == NULL)
    {
      return -ENODEV;
    }

  return eth_phy_read(phy, regaddr, value);
}

int eth_phy_write_reg(FAR struct eth_phy_s *phy, uint8_t regaddr,
                      uint16_t value)
{
  if (phy == NULL)
    {
      return -ENODEV;
    }

  return eth_phy_write(phy, regaddr, value);
}

