/* Everything the driver needs to know about the board's port.
 *
 * The RGMII delay taps are board facts that cannot be discovered at run time
 * -- they come from the vendor DTB -- so they are passed in rather than probed
 * and guessed.  The callbacks are the board's half of the bring-up: pinmuxing
 * the fourteen RGMII pads, driving the PHY's reset line, and naming the PHY.
 *
 * The PHY is named through a callback rather than a handle or an address
 * because it cannot exist until this driver has built the MDIO bus it sits on:
 * the board says *which* part it soldered on, this driver says *how* to reach
 * the bus, and drivers/drivers/ owns everything in between.
 */

struct rk3576_gmac_config_s
{
  /* RGMII delay lines, in 1/8 ns taps.  VCCIO_IOC MISC_CON offset differs
   * per controller *and* per pin group; the board passes the offset of the
   * group it actually muxed.
   */

  uint16_t ioc_offset;
  uint8_t tx_delay;
  uint8_t rx_delay;
  bool tx_delay_ena;
  bool rx_delay_ena;

  /* The port's own MAC address.  Nothing on this board supplies one -- no
   * DTB property, no OTP -- so it is a board decision and it must be in
   * place before the interface is brought up.
   */

  FAR const uint8_t *mac;

  /* Board callbacks.  `pinmux`, `phy_reset` and `phy_attach` are required;
   * set them to NULL only if the board genuinely has nothing to do, in which
   * case the port has no PHY and ifup will fail.
   *
   *   pinmux     mux the RGMII pad group (idempotent: called at boot and on
   *              every ifup)
   *   phy_reset  drive PHYRSTB, true = hold in reset, false = release
   *   phy_attach bind the board's PHY to the MAC's MDIO bus.  It must call
   *              one of the drivers/drivers/ PHY initialisers and return its
   *              handle, or NULL if nothing answered.
   */

  CODE int (*pinmux)(void);
  CODE void (*phy_reset)(bool assert);
  CODE FAR struct eth_phy_s *(*phy_attach)(
        FAR const struct eth_phy_bus_s *bus);
};

