static bool gm_phy_present(FAR struct rk3576_gmac_s *priv, uint8_t addr)
{
  FAR const struct phy_desc_s *desc = priv->cfg->phy;
  uint16_t bmsr;
  uint16_t id1;
  uint16_t id2;

  if (gm_mdio_read(priv, addr, MII_MSR, &bmsr) < 0)
    return false;
  if (bmsr == 0xffff || bmsr == 0x0000)
    return false;

  if (desc->id1 == 0 && desc->id2 == 0)
    {
      /* The descriptor names a part with no PHY ID registers ... presence is
       * the extended-capability bit alone. */
      return (bmsr & MII_MSR_EXTCAP) != 0;
    }

  if (gm_mdio_read(priv, addr, MII_PHYID1, &id1) < 0 ||
      gm_mdio_read(priv, addr, MII_PHYID2, &id2) < 0)
    return false;

  /* id2's low four bits are the revision; imx9 masks them and so do we. */
  return id1 == desc->id1 && (id2 & 0xfff0) == (desc->id2 & 0xfff0);
}
