 * Description:
 *   Force the MDI pairing instead of leaving it to the part's crossover
 *   detection.  PHYCR1's bits only take effect across a reset, so this writes
 *   them and then software-resets the PHY; autonegotiation restarts by itself
 *   after a reset, and gm_phy_start() has not run yet, so the advertisement
 *   written there is not lost.
 *
 *   Forcing MDIX pairs the board the way a switch port would: a straight cable
 *   then reaches an MDI endpoint (a PC, a scope, a router).  That is the right
 *   default for an endpoint whose automatic crossover is not advancing.
 *
 ****************************************************************************/

static int gm_phy_set_mdi(FAR struct rk3576_gmac_s *priv)
{
  uint16_t cr1 = 0;
  uint16_t bmcr = MII_MCR_RESET;
  uint32_t timeout;
  int ret;

  ret = gm_phy_page_read(priv, GM_PHY_PAGE_PHY, GM_PHY_PHYCR1, &cr1);
  if (ret < 0)
    {
      return ret;
    }

  cr1 |= GM_PHYCR1_MDI_MANUAL;
  if (priv->cfg->mdi_mode == RK3576_GMAC_MDI_MDI)
    {
      cr1 |= GM_PHYCR1_MDI_MDI;
    }
  else
    {
      cr1 &= ~GM_PHYCR1_MDI_MDI;
    }

  ret = gm_phy_page_write(priv, GM_PHY_PAGE_PHY, GM_PHY_PHYCR1, cr1);
  if (ret < 0)
    {
      return ret;
    }

  syslog(LOG_INFO, "gmac%d: PHY MDI forced to %s (phycr1 0x%04x)\\n",
         priv->intf,
         priv->cfg->mdi_mode == RK3576_GMAC_MDI_MDI ? "MDI" : "MDIX", cr1);

  /* Software reset: PHYCR1's MDI bits are latched by it.  The bit clears when
   * the reset completes.
   */

  ret = gm_mdio_write(priv, priv->phyaddr, MII_MCR, bmcr);
  if (ret < 0)
    {
      return ret;
    }

  for (timeout = GM_RESET_TIMEOUT; timeout > 0; timeout--)
    {
      ret = gm_mdio_read(priv, priv->phyaddr, MII_MCR, &bmcr);
      if (ret < 0)
        {
          return ret;
        }

      if ((bmcr & MII_MCR_RESET) == 0)
        {
          return OK;
        }

      up_mdelay(1);
    }

  syslog(LOG_ERR, "gmac%d: PHY software reset never completed\\n",
         priv->intf);
  return -ETIMEDOUT;
}

