+int maxio_restart_aneg(struct phy_device *phydev)
+{
+	int ctl = PHY_READ(phydev, MII_BMCR);
+
+	if (ctl < 0)
+		return ctl;
+
+	ctl |= BMCR_ANENABLE | BMCR_ANRESTART;
+
+	
+	ctl &= ~BMCR_ISOLATE;
+
+	return PHY_WRITE(phydev, MII_BMCR, ctl);
+}
