add = '''/****************************************************************************
 * Name: kickpi_k7_eth_reset_probe
 *
 * Description:
 *   Find out whether the PHY reset line actually reaches the part, without a
 *   probe on it.
 *
 *   A PHY's registers go back to their reset values, so: read the
 *   advertisement register, write a value it cannot already hold, confirm the
 *   write stuck, pulse the reset, and read it again.  A value that went back
 *   to what it was before proves the reset arrived; a value still holding what
 *   was written proves it did not, which is what a pin that is not being
 *   driven -- or a net held somewhere else -- looks like from the PHY side.
 *
 *   This is bring-up instrumentation.  It writes the advertisement and redoes
 *   the reset, both of which ifup does again anyway, and it goes away once the
 *   ports link.
 *
 ****************************************************************************/

#define KICKPI_K7_ETH_ANAR_TEST 0x0de1

static void kickpi_k7_eth_reset_probe(int intf, FAR struct gpio_dev_s **handle,
                                      gpio_pinset_t pinset, bool (*reset)(bool))
{
  uint16_t before = 0;
  uint16_t written = 0;
  uint16_t after = 0;
  int ret;

  ret = rk3576_gmac_mdio_read(intf, KICKPI_K7_ETH_PHYADDR, MII_ADVERTISE,
                              &before);
  if (ret < 0)
    {
      syslog(LOG_ERR, "eth%d: reset probe: ANAR unreadable: %d\\n", intf, ret);
      return;
    }

  ret = rk3576_gmac_mdio_write(intf, KICKPI_K7_ETH_PHYADDR, MII_ADVERTISE,
                               KICKPI_K7_ETH_ANAR_TEST);
  if (ret < 0)
    {
      syslog(LOG_ERR, "eth%d: reset probe: ANAR unwritable: %d\\n", intf, ret);
      return;
    }

  rk3576_gmac_mdio_read(intf, KICKPI_K7_ETH_PHYADDR, MII_ADVERTISE, &written);

  reset(true);
  up_mdelay(20);
  reset(false);
  up_mdelay(100);

  rk3576_gmac_mdio_read(intf, KICKPI_K7_ETH_PHYADDR, MII_ADVERTISE, &after);

  syslog(LOG_INFO,
         "eth%d: reset probe: anar was 0x%04x, wrote 0x%04x, reads 0x%04x, "
         "after reset 0x%04x\\n",
         intf, before, KICKPI_K7_ETH_ANAR_TEST, written, after);

  if (written != KICKPI_K7_ETH_ANAR_TEST)
    {
      syslog(LOG_WARNING,
             "eth%d: reset probe inconclusive: the write did not stick\\n",
             intf);
    }
  else if (after == written)
    {
      syslog(LOG_ERR,
             "eth%d: reset probe: the reset never reached the PHY -- ANAR "
             "still holds what was written.  The line is not being driven to "
             "the PHY, or something else holds it.\\n",
             intf);
    }
  else
    {
      syslog(LOG_INFO,
             "eth%d: reset probe: the reset reached the PHY (ANAR back to "
             "0x%04x)\\n",
             intf, after);
    }
}

