 *   oscillator comes up with the supply, and a PHYRSTB pulse does not restart
 *   it: a port that is reset at ifup is left with its analog side -- and so its
 *   reference clock -- stopped, while MDIO, the register file and the bias
 *   resistor all look perfectly healthy.  That is the state this board has been
 *   stuck in, and the vendor kernel never gets there because it resets the PHY
 *   once, when it probes it.
 *
 ****************************************************************************/

static int gm_board_power(FAR struct rk3576_gmac_s *priv, bool reset)
{
  int ret;

  if (priv->cfg->pinmux != NULL)
    {
