  gm_buf_clean(netpkt_getdata(dev, pkt), len);
  gm_desc_sync(desc);

  priv->txnow = next;
  gm_putreg(priv, RK3576_GMAC_DMA_CH0_TXDESC_TAIL_PTR,
            (uint32_t)up_addrenv_va_to_pa(gm_desc(priv->txring, priv->txnow)));

  spin_unlock_irqrestore(&priv->lock, flags);
  return OK;
}

